import SwiftUI
import SwiftData

enum AppTab: Hashable { case today, history, settings }

struct OnboardingView: View {
    let modelContext: ModelContext; @State private var guideID = ""; @FocusState private var isFocused: Bool
    var body: some View { ZStack { TravelWorldBackground(); ScrollView { VStack(spacing: 24) { AssetImage(asset: .earth).frame(width: 128, height: 128).accessibilityHidden(true); IvoryPanel { VStack(spacing: 18) { Text("欢迎来到地球Online").font(FontToken.pageTitle).foregroundStyle(EarthTheme.pageText).multilineTextAlignment(.center); Text("请设置你的ID").font(FontToken.label).foregroundStyle(EarthTheme.pageText.opacity(0.78)); TextField("向导ID", text: $guideID).textFieldStyle(.roundedBorder).focused($isFocused).submitLabel(.done).accessibilityIdentifier("onboarding-guide-id"); Button("开始探索", systemImage: "arrow.right") { createProfile() }.buttonStyle(PixelTravelButtonStyle()).disabled(guideID.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty).accessibilityIdentifier("onboarding-start") } } }.padding(EarthComponent.pagePadding).padding(.top, 42) }.scrollIndicators(.hidden) }.onAppear { isFocused = true } }
    private func createProfile() { let profile = LocalProfile(guideID: guideID.trimmingCharacters(in: .whitespacesAndNewlines)); if UITestConfiguration.runID(environment: ProcessInfo.processInfo.environment, arguments: ProcessInfo.processInfo.arguments) != nil { profile.installID = UITestConfiguration.fixedInstallID }; modelContext.insert(profile); try? modelContext.save() }
}

struct AppShell: View { let profile: LocalProfile; let modelContext: ModelContext; @State private var selected: AppTab
    init(profile: LocalProfile, modelContext: ModelContext, initialTab: AppTab = .today) { self.profile = profile; self.modelContext = modelContext; _selected = State(initialValue: initialTab) }
    var body: some View { TabView(selection: $selected) { TodayView(profile: profile, modelContext: modelContext).tabItem { Label("今日", systemImage: "sun.max.fill") }.tag(AppTab.today); HistoryView(profile: profile).tabItem { Label("历史", systemImage: "clock.arrow.circlepath") }.tag(AppTab.history); SettingsView(profile: profile, modelContext: modelContext).tabItem { Label("设置", systemImage: "gearshape.fill") }.tag(AppTab.settings) }.tint(EarthPalette.deepTeal) }
}

struct TodayView: View { let profile: LocalProfile; let modelContext: ModelContext; @State private var plan: DailyPlan?; @State private var errorText: String?
    var body: some View { ZStack { TravelWorldBackground(); ScrollViewReader { proxy in ScrollView { VStack(alignment: .leading, spacing: 16) { SectionStamp(title: "今日任务", subtitle: "5:00 AM 刷新 · 当前业务日"); IvoryPanel { HStack(spacing: 12) { AssetImage(asset: .airplane).frame(width: 46, height: 42).accessibilityHidden(true); VStack(alignment: .leading, spacing: 3) { Text("今天的旅程已经准备好").font(FontToken.label); Text("每项任务可独立完成，当天可撤销。").font(FontToken.dateTime).foregroundStyle(EarthTheme.pageText.opacity(0.75)) } } }; if let plan { ForEach(plan.instances) { instance in TaskRow(instance: instance, language: profile.languageCode) { toggle(instance) } } } else if errorText == nil { IvoryPanel { ContentUnavailableView("暂无可用任务", systemImage: "tray") } }; if let errorText { IvoryPanel { Text(errorText).foregroundStyle(.red) } }; Color.clear.frame(height: 1).id("today-bottom") }.padding(EarthComponent.pagePadding) }.scrollIndicators(.hidden).onAppear { scrollToBottomIfRequested(proxy, id: "today-bottom") } }; AccessibilityScrollTopMask() }.task { load() } }
    private var service: DailyTaskService { if UITestConfiguration.runID(environment: ProcessInfo.processInfo.environment, arguments: ProcessInfo.processInfo.arguments) != nil { return DailyTaskService(context: modelContext, profile: profile, clock: UITestFixedClock(now: UITestConfiguration.fixedNow), calendar: UITestConfiguration.fixedCalendar, timeZone: UITestConfiguration.fixedTimeZone) }; return DailyTaskService(context: modelContext, profile: profile) }
    private func load() { do { plan = try service.today() } catch { errorText = "无法保存今日计划" } }; private func toggle(_ item: DailyInstance) { do { try service.toggle(item) } catch { errorText = "无法保存完成状态" } }
}

struct TaskRow: View { let instance: DailyInstance; let language: String; let action: () -> Void; private var title: String { language == "en" && !instance.snapshotEn.isEmpty ? instance.snapshotEn : instance.snapshotZh }; private var completed: Bool { instance.completion?.revokedAt == nil && instance.completion != nil }
    var body: some View { Button(action: action) { HStack(alignment: .top, spacing: 12) { GenericTaskIconView(iconKey: instance.iconKey, size: 42); VStack(alignment: .leading, spacing: 7) { Text(title).font(FontToken.taskTitle).foregroundStyle(EarthTheme.pageText).multilineTextAlignment(.leading); HStack(spacing: 6) { TaskTypeBadgeView(type: instance.type); Text(instance.type == "egg" ? "彩蛋任务" : "核心任务").font(FontToken.dateTime) }.foregroundStyle(EarthTheme.pageText); Text(completed ? "已完成 · 点按撤销" : "点按完成任务").font(FontToken.label).foregroundStyle(completed ? EarthPalette.core : EarthTheme.accent) }; Spacer(minLength: 4); Image(systemName: completed ? "checkmark.circle.fill" : "circle").font(.title2).foregroundStyle(completed ? EarthPalette.core : EarthTheme.accent) }.padding(EarthComponent.cardPadding).frame(maxWidth: .infinity, alignment: .leading).background { RoundedRectangle(cornerRadius: EarthComponent.cornerRadius, style: .continuous).fill(EarthTheme.surface.opacity(0.98)).shadow(color: EarthComponent.shadow, radius: 0, x: 3, y: 4) }.overlay(alignment: .bottomTrailing) { Image(instance.type == "egg" ? "egg-task-card-frame-v2" : "core-task-card-frame-v2", bundle: .main).resizable().scaledToFit().frame(width: 112, height: 132).opacity(0.28).allowsHitTesting(false).accessibilityHidden(true) }.overlay(RoundedRectangle(cornerRadius: EarthComponent.cornerRadius, style: .continuous).stroke(EarthTheme.outline, lineWidth: EarthComponent.outlineWidth)) }.buttonStyle(.plain).accessibilityLabel("\(title)，\(instance.type == "egg" ? "彩蛋任务" : "核心任务")，\(completed ? "已完成，双击撤销" : "进行中，双击完成")").accessibilityIdentifier("today-task-\(instance.instanceID)") }
}

struct HistoryView: View { let profile: LocalProfile; @State private var filter = "全部"; @Query private var allInstances: [DailyInstance]
    private var entries: [DailyInstance] { allInstances.filter { $0.plan?.profile?.persistentModelID == profile.persistentModelID && $0.completion?.revokedAt == nil && $0.completion != nil && (filter == "全部" || (filter == "核心" ? $0.type == "core" : $0.type == "egg")) }.sorted { ($0.completion?.completedAt ?? .distantPast) > ($1.completion?.completedAt ?? .distantPast) } }
    var body: some View { ZStack { TravelWorldBackground(); ScrollViewReader { proxy in ScrollView { VStack(alignment: .leading, spacing: 14) { SectionStamp(title: "历史", subtitle: "已经完成的地球Online记录"); IvoryPanel { HStack { AssetImage(asset: .camera).frame(width: 40, height: 34).accessibilityHidden(true); Text(Date.now.formatted(.dateTime.year().month().day().locale(Locale(identifier: profile.languageCode)))).font(FontToken.label) }.accessibilityIdentifier("history-today-date") }; Picker("筛选", selection: $filter) { Text("全部").tag("全部"); Text("核心任务").tag("核心"); Text("彩蛋任务").tag("彩蛋") }.pickerStyle(.segmented).accessibilityIdentifier("history-filter"); if entries.isEmpty { IvoryPanel { ContentUnavailableView("暂无完成记录", systemImage: "clock") } } else { ForEach(entries) { HistoryRow(item: $0, language: profile.languageCode) } }; Color.clear.frame(height: 1).id("history-bottom") }.padding(EarthComponent.pagePadding) }.scrollIndicators(.hidden).onAppear { scrollToBottomIfRequested(proxy, id: "history-bottom") } }; AccessibilityScrollTopMask() } }
}
private struct HistoryRow: View { let item: DailyInstance; let language: String; private var title: String { language == "en" && !item.snapshotEn.isEmpty ? item.snapshotEn : item.snapshotZh }; private var time: String { (item.completion?.completedAt ?? .now).formatted(.dateTime.year().month().day().hour().minute().locale(Locale(identifier: language))) }
    var body: some View { IvoryPanel { HStack(alignment: .top, spacing: 12) { GenericTaskIconView(iconKey: item.iconKey, size: 32); VStack(alignment: .leading, spacing: 7) { Text(title).font(FontToken.taskTitle).foregroundStyle(EarthTheme.pageText).multilineTextAlignment(.leading); HStack(spacing: 6) { TaskTypeBadgeView(type: item.type); Text(item.type == "egg" ? "彩蛋任务" : "核心任务").font(FontToken.dateTime) }; Text("完成于 \(time)").font(FontToken.dateTime).foregroundStyle(EarthTheme.pageText.opacity(0.72)) }; Spacer(minLength: 0) } }.accessibilityElement(children: .combine).accessibilityIdentifier("history-entry-\(item.instanceID)") }
}

struct SettingsView: View { let profile: LocalProfile; let modelContext: ModelContext; @State private var notificationState: NotificationAuthorizationState = .notDetermined; @State private var notificationsEnabled = false; private let notifications = NotificationService()
    var body: some View { ZStack { TravelWorldBackground(); ScrollViewReader { proxy in ScrollView { VStack(alignment: .leading, spacing: 14) { SectionStamp(title: "设置", subtitle: "本地偏好与旅行装备"); IvoryPanel { ViewThatFits(in: .horizontal) { HStack(spacing: 12) { avatar; identity }; VStack(alignment: .leading, spacing: 8) { avatar; identity } }.accessibilityIdentifier("settings-guide-id") }; panel { row("通知", id: "settings-notifications", binding: notificationBinding); Divider(); row("音乐", id: "settings-music", binding: binding(\.musicEnabled)); Divider(); row("音效", id: "settings-sound", binding: binding(\.soundEffectsEnabled)) }; panel { VStack(alignment: .leading, spacing: 8) { Text("语言").font(FontToken.label); Picker("语言", selection: binding(\.languageCode)) { Text("简体中文").tag("zh-Hans"); Text("English").tag("en") }.pickerStyle(.segmented).accessibilityIdentifier("settings-language") }; Divider(); VStack(alignment: .leading, spacing: 4) { Text("每日刷新").font(FontToken.label); Text("5:00 AM").font(FontToken.taskTitle).foregroundStyle(EarthTheme.pageText) }; Divider(); NavigationLink("关于我们") { AboutView() }.font(FontToken.label) }; AssetImage(asset: .suitcase).frame(width: 92, height: 92).frame(maxWidth: .infinity).accessibilityHidden(true); Color.clear.frame(height: 1).id("settings-bottom") }.padding(EarthComponent.pagePadding) }.scrollIndicators(.hidden).onAppear { scrollToBottomIfRequested(proxy, id: "settings-bottom") } }; AccessibilityScrollTopMask() }.task { await refresh() }.onReceive(NotificationCenter.default.publisher(for: UIApplication.willEnterForegroundNotification)) { _ in Task { await refresh() } } }
    private var avatar: some View { AssetImage(asset: .earth).frame(width: 54, height: 54).accessibilityHidden(true) }; private var identity: some View { VStack(alignment: .leading, spacing: 4) { Text("向导ID").font(FontToken.dateTime).foregroundStyle(EarthTheme.pageText.opacity(0.75)); Text(profile.guideID).font(FontToken.taskTitle).foregroundStyle(EarthTheme.pageText).fixedSize(horizontal: false, vertical: true).layoutPriority(1) } }; private func panel<Content: View>(@ViewBuilder _ content: () -> Content) -> some View { IvoryPanel { VStack(alignment: .leading, spacing: 12, content: content) } }; private func row(_ name: String, id: String, binding: Binding<Bool>) -> some View { HStack { Text(name).font(FontToken.label).foregroundStyle(EarthTheme.pageText).layoutPriority(1); Spacer(); Toggle("", isOn: binding).labelsHidden().tint(EarthPalette.teal).accessibilityLabel(name).accessibilityIdentifier(id) } }; private var notificationBinding: Binding<Bool> { Binding(get: { notificationsEnabled }, set: { enabled in notificationsEnabled = enabled; Task { if enabled { if notificationState == .denied { notifications.openSettings() } else { await notifications.requestAndSchedule(languageCode: profile.languageCode) } } else { await notifications.cancel() }; await refresh() } }) }; private func refresh() async { notificationState = await notifications.status(); notificationsEnabled = notificationState == .authorized || notificationState == .provisional }; private func binding<T>(_ keyPath: ReferenceWritableKeyPath<LocalProfile, T>) -> Binding<T> { Binding(get: { profile[keyPath: keyPath] }, set: { profile[keyPath: keyPath] = $0; try? modelContext.save() }) }
}
struct AboutView: View { private let version = Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String; var body: some View { ZStack { TravelWorldBackground(); ScrollView { IvoryPanel { VStack(alignment: .leading, spacing: 14) { Text("关于我们").font(FontToken.pageTitle); Text("地球Online小向导是仅在本机运行的每日任务向导。"); Text("隐私政策与用户协议：测试版不收集、不上传个人数据；数据仅保存在当前设备。").font(FontToken.label); if let version { Text("版本 \(version)").font(FontToken.dateTime) } } }.padding(EarthComponent.pagePadding) } }.navigationTitle("关于我们") } }

private func scrollToBottomIfRequested(_ proxy: ScrollViewProxy, id: String) {
#if DEBUG
    guard ProcessInfo.processInfo.environment["EARTH_GUIDE_VISUAL_VERIFY_SCROLL_TO_BOTTOM"] == "1" else { return }
    DispatchQueue.main.async { proxy.scrollTo(id, anchor: .bottom) }
#endif
}

private struct AccessibilityScrollTopMask: View {
    @Environment(\.dynamicTypeSize) private var dynamicTypeSize
    var body: some View {
        if dynamicTypeSize.isAccessibilitySize {
            EarthPalette.sky.frame(height: 78).frame(maxHeight: .infinity, alignment: .top).ignoresSafeArea(edges: .top).allowsHitTesting(false).accessibilityHidden(true)
        }
    }
}
